SUMMARIES = [
"The first Congress, the adoption of the name Gereja Gerakan Pentakosta and its emblem, and the appointment of central leaders.",
"The formation of the Spiritual Council, the 1964–1968 leadership, and the early development of GGP's youth organization.",
"The change from Congress to General Assembly and the assignment of Central Council ministry responsibilities.",
"The assembly at Wisma Oikoumene, the 1972–1976 leadership, and the appointment of GGP's Spiritual Father.",
"The author's account of proceedings in Bongkudai Baru and the Central Council leadership for 1976–1980.",
"Central Council appointments and preparations for General Assembly VI in 1980.",
"A generational transition, renewed assembly procedures, and Central Council ministry programs for 1980–1984.",
"Ministry growth, partner church relationships, and a documentary account of Pdt. Henk Thiessen's life.",
"The assembly in Pineleng, Central Council leadership for 1988–1992, and limits on the Chairperson's tenure.",
"The assembly at Wisma Kinasih, the Minister of Religious Affairs' attendance, and the 1992–1996 leadership.",
"Proceedings at Grand Hotel Lembang and changes to terms of office and leadership for 1996–2001.",
"The vision of becoming the Church Christ desires, leadership for 2001–2006, and accounts of organizational life in that period.",
"Central Council appointments, ministry departments, and assembly resolutions at the STTP Mooat campus.",
"Proceedings at Ecclesia Christi and the Central Council leadership for 2010–2015.",
"Leadership for 2015–2021, assembly resolutions, and the postponement of the next assembly during the pandemic.",
"The hybrid assembly in October 2021 and the MP, DP, and BPP leadership for 2021–2026.",
]

def build():
    source = json.loads(SOURCE.read_text(encoding="utf-8"))
    pattern = re.compile("|".join(re.escape(term) for term in sorted(GLOSSARY, key=len, reverse=True)))
    chapters = {}
    for index, chapter in enumerate(source["chapters"]):
        blocks = []
        for block_index, block in enumerate(chapter["blocks"]):
            override = TRANSLATIONS[chapter["year"]].get(block_index)
            if override:
                text = override
            elif block["kind"] == "figure":
                text = f"Documentation in Benih yang Tumbuh, page {block['bookPage']}."
            elif block["kind"] == "entry":
                text = pattern.sub(lambda match: GLOSSARY[match.group()], block["text"])
            else:
                raise ValueError(f"Missing narrative translation: {chapter['slug']} block {block_index}")
            blocks.append(text)
        title = chapter["title"].replace("Kongres", "Congress").replace("Sidang Raya", "General Assembly").replace("Sidang Pelengkap Pusat", "Central Supplementary Assembly")
        location = chapter["location"].replace("Jawa Barat", "West Java").replace("Jawa Timur", "East Java").replace("Sulawesi Utara", "North Sulawesi").replace("Kampus", "Campus")
        chapters[chapter["slug"]] = {"title": title, "location": location, "summary": SUMMARIES[index], "blocks": blocks}
    output = {"language": "en", "sourceSha256": source["sourceSha256"], "sourceTextSha256": hashlib.sha256(SOURCE.read_text(encoding="utf-8").encode("utf-8")).hexdigest(), "chapters": chapters}
    (SOURCE.parent / "benih-yang-tumbuh.en.json").write_text(json.dumps(output, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

if __name__ == "__main__":
    build()
